// Glowing red eyes, drawn again on top of the Bat Queen's darkness.
function batEyes(px,py){glow(px,py+1,14,'#ff3b4f',.8);ctx.fillStyle='#ff5a6a';ctx.beginPath();ctx.arc(px-3,py+1,2.4,0,TAU);ctx.arc(px+3,py+1,2.4,0,TAU);ctx.fill()}
function drawBossLayer(){if(!boss||boss.phase==='clear'||boss.phase==='versus')return;
 if(boss.wind){const d=boss.wind.dir,k=Math.min(1,boss.wind.time/.5);ctx.save();ctx.strokeStyle=`rgba(255,255,255,${.55*k})`;ctx.lineWidth=3;ctx.lineCap='round';for(let i=0;i<14;i++){const y=H*.06+i*H/14,sp=(boss.animT*620*(1+(i%3)*.3)+i*97)%(W+260)-130,x0=d>0?sp:W-sp;for(const [lw,c] of [[7,`rgba(40,90,170,${.35*k})`],[3,`rgba(255,255,255,${.85*k})`]]){ctx.strokeStyle=c;ctx.lineWidth=lw;ctx.beginPath();ctx.moveTo(x0,y);ctx.quadraticCurveTo(x0-d*60,y-8,x0-d*140,y);ctx.stroke()}}ctx.restore()}const f=boss.fatal;if(f&&f.def.under)f.def.under(f.p,boss,f);drawBossBody(boss);for(const s of boss.shots)drawShot(s)}
function drawBossFx(){const b=boss;
 // Blackout: the screen goes dark except a small glow around the balloon; the hunting bats show only their eyes.
 if(b&&b.dark){const d=b.dark,a=Math.max(0,Math.min(1,d.t/.4,(d.dur-d.t)/.5))*.94,bx=x*W,by=balloonY(),g=ctx.createRadialGradient(bx,by,46,bx,by,165);g.addColorStop(0,'rgba(8,4,20,0)');g.addColorStop(1,`rgba(8,4,20,${a})`);ctx.fillStyle=g;ctx.fillRect(-OX,-20,SW,H+40);
  for(const s of b.shots)if(s.style==='eyebat'){ctx.save();ctx.translate(s.x,s.y);ctx.rotate(Math.atan2(s.vy||1,s.vx||0)+Math.PI/2);batEyes(0,0);ctx.restore()}}
 const f=b&&b.fatal;if(f&&boss.phase==='fatality'&&f.def.draw)f.def.draw(f.p,boss,f)}

// ---------- Fatalities: one finishing move per balloon skin ----------
// Comic words (POW!, SLASH! and so on) show only in the tutorial.
const fxWord=(...a)=>{if(tipsOn())popup(...a)};
